<script setup lang="ts">
// The timeline's playhead: a snail (snailglorp_exp_2.svg) with its head on the current time. It has three moods of
// two frames each: crawling while the VOD plays (one frame a second at normal speed, faster or slower with the playback
// speed), asleep while paused, and floating while the time is being moved.
// The body takes the site's accent; the shell takes `shell` (the game being played), or the drawing's own yellow when
// there is none. The darker and lighter shades are mixed from those.
import { computed } from 'vue'
import type { SnailMode } from '../composables/useTimeline'

export type { SnailMode }

const props = withDefaults(defineProps<{ mode: SnailMode; rate?: number; shell?: string }>(), { rate: 1 })

/** Seconds per frame. */
const FRAME: Record<SnailMode, number> = { walk: 1, sleep: 1.5, float: 0.5 }
const style = computed(() => ({
  '--snail-frame': `${props.mode === 'walk' && props.rate > 0 ? FRAME.walk / props.rate : FRAME[props.mode]}s`,
  ...(props.shell ? { '--snail-shell': props.shell } : {}),
}))
</script>

