<style scoped>
.snail {
  --snail-body: var(--vx-accent);
  --snail-shell: #d3bc5f;
  display: block;
  overflow: visible;
}
.body { fill: var(--snail-body); }
.line { stroke: color-mix(in oklab, var(--snail-body), black 20%); }
.shell-line { stroke: var(--snail-shell); }
.shell-fill { fill: color-mix(in oklab, var(--snail-shell), white 45%); }
.eye { fill: #4d4d4d; stroke: #4d4d4d; }

/* Only the current mood shows, its two frames taking turns. */
.frame { visibility: hidden; }
.snail[data-mode='walk'] .walk .f1,
.snail[data-mode='sleep'] .sleep .f1,
.snail[data-mode='float'] .float .f1 { visibility: visible; animation: first calc(2 * var(--snail-frame)) steps(1) infinite; }
.snail[data-mode='walk'] .walk .f2,
.snail[data-mode='sleep'] .sleep .f2,
.snail[data-mode='float'] .float .f2 { animation: second calc(2 * var(--snail-frame)) steps(1) infinite; }
@keyframes first { 50% { visibility: hidden; } }
@keyframes second { 50% { visibility: visible; } }
@media (prefers-reduced-motion: reduce) {
  .frame { animation: none !important; }
}
</style>
